import { basename, join } from 'node:path';
import { writeJson } from './fs.js';
import { computeTreeDigest } from './tree-digest.js';
import { computeMigrationImmutableDigest, computeSourceEvidencePolicyDigest, computeSourceProvenanceDigest, createSourceEvidencePolicy, SOURCE_EVIDENCE_POLICY_PATH, SOURCE_MANIFEST_PATH, SOURCE_SNAPSHOT_POLICY, } from './source-provenance.js';
export async function writeMigrationProvenance(params) {
    const sourceSnapshotDigest = await computeTreeDigest(join(params.workspaceRoot, 'upstream-source'));
    const templateSnapshotDigest = await computeTreeDigest(params.template.root);
    const snapshotCompleteness = params.sourceCopy.omissions.length > 0 ? 'partial' : 'complete';
    const sourceEvidencePolicy = createSourceEvidencePolicy(params.sourceCopy.sourceManifestDigest);
    const sourceEvidencePolicyDigest = computeSourceEvidencePolicyDigest(sourceEvidencePolicy);
    const createdAt = new Date().toISOString();
    const sourceRecord = {
        kind: params.prepared.sourceKind,
        url: params.sourceUrl,
        repo: params.prepared.repoSlug,
        commit: params.prepared.sourceCommit,
        ref: params.prepared.sourceRef,
        dirty: params.prepared.sourceDirty,
        license: params.analysis.license,
        snapshotPath: 'upstream-source',
        snapshotDigest: sourceSnapshotDigest,
        snapshotPolicy: SOURCE_SNAPSHOT_POLICY,
        snapshotCompleteness,
        omissions: params.sourceCopy.omissions,
        sourceManifestPath: SOURCE_MANIFEST_PATH,
        sourceManifestDigest: params.sourceCopy.sourceManifestDigest,
        sourceEvidencePolicyPath: SOURCE_EVIDENCE_POLICY_PATH,
        sourceEvidencePolicyDigest,
    };
    const templateRecord = {
        kind: params.templateSource?.sourceKind ?? 'local',
        url: params.templateSource?.sourceUrl ?? `local:${basename(params.template.root)}`,
        requestedRef: params.templateSource?.requestedRef ?? null,
        resolvedRef: params.templateSource?.resolvedRef ?? params.template.ref,
        commit: params.templateSource?.commit ?? params.template.commit,
        version: params.template.version,
        policyApplied: params.template.policyApplied,
        dirty: params.templateSource?.dirty ?? params.template.dirty,
        snapshotDigest: templateSnapshotDigest,
    };
    const analysisRecord = {
        appType: params.analysis.appType,
        strategy: params.analysis.strategy,
        score: params.analysis.score,
        recommendation: params.analysis.recommendation,
        risks: params.analysis.risks,
    };
    const migrationImmutableDigest = computeMigrationImmutableDigest({
        schemaVersion: 'taku.subapp-migration.v2',
        createdAt,
        source: sourceRecord,
        template: templateRecord,
        analysis: analysisRecord,
    });
    const sourceBinding = {
        sourceKind: params.prepared.sourceKind,
        sourceRepo: params.prepared.repoSlug,
        sourceUrl: params.sourceUrl,
        sourceCommit: params.prepared.sourceCommit,
        sourceRef: params.prepared.sourceRef,
        sourceDirty: params.prepared.sourceDirty,
        sourceLicense: params.analysis.license,
        snapshotPath: 'upstream-source',
        snapshotDigest: sourceSnapshotDigest,
        snapshotPolicy: SOURCE_SNAPSHOT_POLICY,
        snapshotCompleteness,
        omissions: params.sourceCopy.omissions,
        sourceManifestPath: SOURCE_MANIFEST_PATH,
        sourceManifestDigest: params.sourceCopy.sourceManifestDigest,
        sourceEvidencePolicyPath: SOURCE_EVIDENCE_POLICY_PATH,
        sourceEvidencePolicyDigest,
        migrationImmutableDigest,
    };
    await writeJson(join(params.workspaceRoot, SOURCE_MANIFEST_PATH), params.sourceCopy.sourceManifest);
    await writeJson(join(params.workspaceRoot, SOURCE_EVIDENCE_POLICY_PATH), sourceEvidencePolicy);
    await writeJson(join(params.workspaceRoot, '.taku', 'migration.json'), {
        schemaVersion: 'taku.subapp-migration.v2',
        status: 'workspace',
        createdAt,
        source: {
            ...sourceRecord,
            migrationImmutableDigest,
            provenanceDigest: computeSourceProvenanceDigest(sourceBinding),
        },
        template: templateRecord,
        analysis: {
            ...analysisRecord,
            riskResolutions: [],
        },
    });
}
